import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BZO4qERu.js";const m=JSON.parse('{"title":"Telegram Channel Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/channels/telegram.md","filePath":"integrations/channels/telegram.md","lastUpdated":1790952322000}'),n={name:"integrations/channels/telegram.md"};function i(l,e,s,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="telegram-channel-configuration" tabindex="-1">Telegram Channel Configuration <a class="header-anchor" href="#telegram-channel-configuration" aria-label="Permalink to &quot;Telegram Channel Configuration&quot;">​</a></h1><p>Connect your Memoh bot to Telegram — one of the most fully supported channels in Memoh, with streaming responses, Markdown formatting, and attachments.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A Telegram account; you create the bot by talking to <strong>@BotFather</strong>.</li><li>A Memoh bot; channels are configured from its <strong>Platforms</strong> tab.</li></ul><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><h3 id="_1-in-telegram-create-a-bot-with-botfather" tabindex="-1">1. In Telegram, create a bot with @BotFather <a class="header-anchor" href="#_1-in-telegram-create-a-bot-with-botfather" aria-label="Permalink to &quot;1. In Telegram, create a bot with @BotFather&quot;">​</a></h3><ol><li>Open Telegram and search for the official <strong>@BotFather</strong> bot.</li><li>Send the <code>/newbot</code> command.</li><li>Follow the prompts: <ul><li><strong>Name</strong>: a display name for your bot (e.g., <code>My Memoh Bot</code>).</li><li><strong>Username</strong>: a unique username ending in <code>bot</code> (e.g., <code>my_memoh_bot</code>).</li></ul></li><li>BotFather replies with an <strong>API Token</strong> (e.g., <code>123456789:ABCdefGHIjklMNOpqrsTUVwxyz</code>). <strong>Keep this token secret.</strong></li></ol><blockquote><p>Official guide: <a href="https://core.telegram.org/bots/tutorial" target="_blank" rel="noreferrer">Telegram Bot Tutorial</a></p></blockquote><h3 id="_2-in-memoh-add-the-telegram-channel" tabindex="-1">2. In Memoh, add the Telegram channel <a class="header-anchor" href="#_2-in-memoh-add-the-telegram-channel" aria-label="Permalink to &quot;2. In Memoh, add the Telegram channel&quot;">​</a></h3><ol><li>Open your bot&#39;s detail page and select the <strong>Platforms</strong> tab.</li><li>Click <strong>Add Channel</strong> and select <strong>Telegram</strong>.</li><li>Paste the <strong>API Token</strong> into the credentials field.</li><li>Click <strong>Save and Enable</strong>.</li></ol><h2 id="credentials" tabindex="-1">Credentials <a class="header-anchor" href="#credentials" aria-label="Permalink to &quot;Credentials&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>API Token</strong></td><td>The token BotFather issues when you create the bot (e.g., <code>123456789:ABC...</code>). Keep it secret.</td></tr></tbody></table><h2 id="verify" tabindex="-1">Verify <a class="header-anchor" href="#verify" aria-label="Permalink to &quot;Verify&quot;">​</a></h2><p>Open a direct chat with your bot in Telegram and send <code>/help</code>. If the bot replies with its command list, the channel is working.</p><h2 id="group-chats" tabindex="-1">Group chats <a class="header-anchor" href="#group-chats" aria-label="Permalink to &quot;Group chats&quot;">​</a></h2><p>Telegram group chats are supported. Add the bot to a group and @mention it by its username to talk to it there.</p><h2 id="disable-and-rotate-credentials" tabindex="-1">Disable and rotate credentials <a class="header-anchor" href="#disable-and-rotate-credentials" aria-label="Permalink to &quot;Disable and rotate credentials&quot;">​</a></h2><p>You can disable or remove this channel at any time from the bot&#39;s <strong>Platforms</strong> tab. To rotate the token, update the <strong>API Token</strong> field and save.</p>',18)])])}const u=t(n,[["render",i]]);export{m as __pageData,u as default};
